{
  "info": {
    "description": "Date deschise, doar citire, fără cheie. Limită: 60 cereri/minut pe IP, rafală 20. Fiecare răspuns are `provenienta` (surse, data observării, încredere, licență, citare). API-ul arată doar ce arată site-ul: persoanele apar numai prin funcția lor publică. Serverul MCP e la /mcp."
  },
  "path": "/v1/companii",
  "method": "get",
  "operationId": "companii",
  "summary": "Lista companiilor de stat și locale (după nume sau CUI)",
  "parameters": [
    {
      "name": "q",
      "in": "query",
      "required": false,
      "description": "căutare în nume, fără diacritice, 2–80 de caractere",
      "schema": {
        "type": "string"
      }
    },
    {
      "name": "judet",
      "in": "query",
      "required": false,
      "description": "județul sediului",
      "schema": {
        "type": "string"
      }
    },
    {
      "name": "nivel",
      "in": "query",
      "required": false,
      "description": "central sau local",
      "schema": {
        "type": "string",
        "enum": [
          "central",
          "local"
        ]
      }
    },
    {
      "name": "categorie",
      "in": "query",
      "required": false,
      "description": "SOC, RA, FIL, INST",
      "schema": {
        "type": "string"
      }
    },
    {
      "name": "tutela_siruta",
      "in": "query",
      "required": false,
      "description": "companiile primăriei cu acest SIRUTA",
      "schema": {
        "type": "string"
      }
    },
    {
      "name": "mama",
      "in": "query",
      "required": false,
      "description": "filialele companiei-mamă cu acest CUI",
      "schema": {
        "type": "string"
      }
    },
    {
      "name": "limit",
      "in": "query",
      "required": false,
      "description": "rânduri pe pagină (implicit 25, maximum 100)",
      "schema": {
        "type": "integer",
        "minimum": 1,
        "maximum": 100,
        "default": 25
      }
    },
    {
      "name": "offset",
      "in": "query",
      "required": false,
      "description": "deplasarea: câte rânduri se sar. Fără plafon practic: orice listă se parcurge până la capăt cu offset += limit cât timp `paginare.are_urmatoarea`; `paginare.total` spune câte rânduri are filtrul",
      "schema": {
        "type": "integer",
        "minimum": 0,
        "maximum": 99999999,
        "default": 0
      }
    }
  ]
}

